/**
 * Creates an origin message copy (the original copy generated by the sender node).
 * Has no predecessor sender (receivedFromNodeId is null) and 0 initial hops.
 */
export function createOriginCopy(message, holderNodeId) {
    return {
        messageId: message.id,
        message,
        holderNodeId,
        receivedAtSimTime: message.createdAtSimTime,
        receivedFromNodeId: null,
        hopCount: 0,
        status: "HOLDING",
        isOriginCopy: true,
    };
}
/**
 * Creates a forwarded message copy received from a peer in the mesh.
 * Increments hop count and records predecessor node ID.
 */
export function createForwardedCopy(message, receiverNodeId, senderNodeId, receivedAtSimTime, priorHopCount) {
    return {
        messageId: message.id,
        message,
        holderNodeId: receiverNodeId,
        receivedAtSimTime,
        receivedFromNodeId: senderNodeId,
        hopCount: priorHopCount + 1,
        status: "HOLDING",
        isOriginCopy: false,
    };
}
